package qdrant;
option csharp_namespace = "Qdrant.Client.Grpc";

// Service to read raw files from a collection's on-disk storage directory.
service StorageRead {
  // Check whether a file exists at the given path within a collection.
  rpc FileExists(FileExistsRequest) returns (FileExistsResponse) {}
  // List files within a collection whose relative path starts with a prefix.
  rpc ListFiles(ListFilesRequest) returns (ListFilesResponse) {}
  // Get the byte length of a file within a collection.
  rpc FileLength(FileLengthRequest) returns (FileLengthResponse) {}
  // Read a byte range from a file within a collection.
  rpc ReadBytes(ReadBytesRequest) returns (ReadBytesResponse) {}
  // Read a byte range from a file within a collection, streaming the result in chunks.
  rpc ReadBytesStream(ReadBytesStreamRequest) returns (stream ReadBytesStreamResponse) {}
  // Read the whole contents of a file within a collection.
  rpc ReadWhole(ReadWholeRequest) returns (ReadWholeResponse) {}
  // Read multiple byte ranges from a single file within a collection.
  rpc ReadBatch(ReadBatchRequest) returns (ReadBatchResponse) {}
  // Read byte ranges from multiple files within a collection.
  rpc ReadMulti(ReadMultiRequest) returns (ReadMultiResponse) {}
}

message FileExistsRequest {
  // Name of the collection
  string collection_name = 1;
  // Path to the file, relative to the collection directory
  string path = 2;
}

message FileExistsResponse {
  // Whether the file exists
  bool exists = 1;
}

message ListFilesRequest {
  // Name of the collection
  string collection_name = 1;
  // Prefix used to filter files by their relative path
  string prefix_path = 2;
}

message ListFilesResponse {
  // Paths relative to the collection directory
  repeated string paths = 1;
}

message FileLengthRequest {
  // Name of the collection
  string collection_name = 1;
  // Path to the file, relative to the collection directory
  string path = 2;
}

message FileLengthResponse {
  // Size of the file in bytes
  uint64 length = 1;
}

message ReadBytesRequest {
  // Name of the collection
  string collection_name = 1;
  // Path to the file, relative to the collection directory
  string path = 2;
  // Offset from the beginning of the file, in bytes
  uint64 byte_offset = 3;
  // Number of bytes to read
  uint64 length = 4;
}

message ReadBytesResponse {
  // Requested bytes
  bytes data = 1;
}

message ReadBytesStreamRequest {
  // Name of the collection
  string collection_name = 1;
  // Path to the file, relative to the collection directory
  string path = 2;
  // Offset from the beginning of the file, in bytes
  uint64 byte_offset = 3;
  // Number of bytes to read
  uint64 length = 4;
}

message ReadBytesStreamResponse {
  // Chunk of the requested bytes
  bytes data = 1;
}

message ReadWholeRequest {
  // Name of the collection
  string collection_name = 1;
  // Path to the file, relative to the collection directory
  string path = 2;
}

message ReadWholeResponse {
  // Complete file contents
  bytes data = 1;
}

message ReadBatchRange {
  // Offset from the beginning of the file, in bytes
  uint64 byte_offset = 1;
  // Number of bytes to read
  uint64 length = 2;
}

message ReadBatchRequest {
  // Name of the collection
  string collection_name = 1;
  // Path to the file, relative to the collection directory
  string path = 2;
  // Ranges to read from the file
  repeated ReadBatchRange ranges = 3;
}

message ReadBatchResponse {
  // One byte slice per requested range, in request order
  repeated bytes data = 1;
}

message ReadMultiEntry {
  // Path to the file, relative to the collection directory
  string path = 1;
  // Offset from the beginning of the file, in bytes
  uint64 byte_offset = 2;
  // Number of bytes to read
  uint64 length = 3;
}

message ReadMultiRequest {
  // Name of the collection
  string collection_name = 1;
  // Reads to perform, potentially across different files
  repeated ReadMultiEntry reads = 2;
}

message ReadMultiResponse {
  // One byte slice per requested read, in request order
  repeated bytes data = 1;
}
