/// Validate a client-supplied relative path before it is used to access the
/// filesystem.
///
/// Rejects path traversal (`..` components) as well as `.`/`./`-prefixed paths.
fn validate_path(path: &str) -> Result<(), Status> {
    if path == "." || path.starts_with("./") {
        return Err(Status::invalid_argument(
            "Invalid path: path must not be '.' or start with './'",
        ));
    }

    for component in Path::new(path).components() {
        if let Component::ParentDir = component {
            return Err(Status::invalid_argument(
                "Invalid path component: '..' is not allowed",
            ));
        }
    }

