    std::fs::create_dir_all(&dir).unwrap();
    dir
}

#[test]
fn test_storage_read_behavior() {
    let tmp = tempfile::Builder::new().prefix("srt").tempdir().unwrap();
    let storage_path = tmp.path().to_path_buf();
    let dispatcher = build_dispatcher(storage_path.clone());
    let service = StorageReadService::new(dispatcher);

    let coll_dir = make_collection(&storage_path, "coll");
    std::fs::write(coll_dir.join("data.bin"), b"hello world").unwrap();
    std::fs::write(coll_dir.join("data.other"), b"xxxx").unwrap();
    std::fs::write(coll_dir.join("empty.bin"), b"").unwrap();

    let rt = Runtime::new().unwrap();

    // file_exists
    let r = rt.block_on(service.file_exists(req(
        FileExistsRequest { collection_name: "coll".into(), path: "data.bin".into() },
        full_auth(),
    ))).unwrap();
    assert!(r.into_inner().exists);
    let r = rt.block_on(service.file_exists(req(
        FileExistsRequest { collection_name: "coll".into(), path: "nope.bin".into() },
        full_auth(),
    ))).unwrap();
    assert!(!r.into_inner().exists);

    // list_files with prefix
    let r = rt.block_on(service.list_files(req(
        ListFilesRequest { collection_name: "coll".into(), prefix_path: "data".into() },
        full_auth(),
    ))).unwrap();
    let mut paths = r.into_inner().paths;
    paths.sort();
    assert_eq!(paths, vec!["data.bin".to_string(), "data.other".to_string()]);

    // file_length
    let r = rt.block_on(service.file_length(req(
        FileLengthRequest { collection_name: "coll".into(), path: "data.bin".into() },
        full_auth(),
    ))).unwrap();
    assert_eq!(r.into_inner().length, 11);

    // file_length missing collection => NotFound
    let e = rt.block_on(service.file_length(req(
        FileLengthRequest { collection_name: "ghost".into(), path: "data.bin".into() },
        full_auth(),
    ))).unwrap_err();
    assert_eq!(e.code(), tonic::Code::NotFound);

    // read_bytes
    let r = rt.block_on(service.read_bytes(req(
        ReadBytesRequest { collection_name: "coll".into(), path: "data.bin".into(), byte_offset: 6, length: 5 },
        full_auth(),
    ))).unwrap();
    assert_eq!(r.into_inner().data, b"world");

    // read_bytes out of range
    let e = rt.block_on(service.read_bytes(req(
        ReadBytesRequest { collection_name: "coll".into(), path: "data.bin".into(), byte_offset: 6, length: 100 },
        full_auth(),
    ))).unwrap_err();
    assert_eq!(e.code(), tonic::Code::OutOfRange);

    // read_whole
    let r = rt.block_on(service.read_whole(req(
        ReadWholeRequest { collection_name: "coll".into(), path: "data.bin".into() },
        full_auth(),
    ))).unwrap();
    assert_eq!(r.into_inner().data, b"hello world");

    // read_batch
    let r = rt.block_on(service.read_batch(req(
        ReadBatchRequest {
            collection_name: "coll".into(),
            path: "data.bin".into(),
            ranges: vec![
                ReadBatchRange { byte_offset: 0, length: 5 },
                ReadBatchRange { byte_offset: 6, length: 5 },
            ],
        },
        full_auth(),
    ))).unwrap();
    let data = r.into_inner().data;
    assert_eq!(data, vec![b"hello".to_vec(), b"world".to_vec()]);

    // read_multi
    let r = rt.block_on(service.read_multi(req(
        ReadMultiRequest {
            collection_name: "coll".into(),
            reads: vec![
                ReadMultiEntry { path: "data.bin".into(), byte_offset: 0, length: 5 },
                ReadMultiEntry { path: "data.other".into(), byte_offset: 0, length: 4 },
            ],
        },
        full_auth(),
    ))).unwrap();
    assert_eq!(r.into_inner().data, vec![b"hello".to_vec(), b"xxxx".to_vec()]);

    // read_multi empty path => InvalidArgument
    let e = rt.block_on(service.read_multi(req(
        ReadMultiRequest {
            collection_name: "coll".into(),
            reads: vec![ReadMultiEntry { path: "".into(), byte_offset: 0, length: 0 }],
        },
        full_auth(),
    ))).unwrap_err();
    assert_eq!(e.code(), tonic::Code::InvalidArgument);\
